              box(ctx, C, bx + cw1 + ag, cy, cw2, chh, C.know, { r: 6, tint: 0.12, lw: 1.2 });
              txt(ctx, C, "«момент ПРОТИВОПОЛОЖНОГО знака»", bx + cw1 + ag + cw2 / 2, cy + chh / 2 + 0.5, { size: hdr ? 9.5 : 11.5, wt: 700, align: "center", maxW: cw2 - 8, min: 7.5 });
