              txt(ctx, C, "«машиночитаемая и машинопонимаемая форма»", x2 + bw2 / 2, y2 + bh * 0.72, { size: 10, color: C.ink2, align: "center", maxW: bw2 - 12, min: 7.5 });
              if (narrow) P.arrow(m + rw / 2, y1 + bh + 2, m + rw / 2, y2 - 2, COL.p2, 2.4, 8);
              else P.arrow(x1 + bw1 + 3, y1 + bh / 2, x2 - 3, y1 + bh / 2, COL.p2, 2.6, 9);
