      const FOC = [[], [7], [6], [4], [4], [1, 4], [7, 0]];                 // มุมที่ล้อมวงในแต่ละขั้น
      const nets = b => hopNets(b);
      const cellsOf = (b, tails, hi) => nets(b).map((n, j) => ({ v: b[j], l2: "net " + sg(n) + (tails[j] || ""), hi: hi.indexOf(j) >= 0 }));
      /* แถบนิวรอนของแต่ละขั้น (ขั้นที่ 1 ไม่มี) */
