  const gn = (v, d) => { const s = nf(v, d); return s.indexOf(",") < 0 ? s : s.replace(/0+$/, "").replace(/,$/, ""); };
  const sg = (v, d) => { const s = gn(v, d); return v > 0 && s !== "0" ? "+" + s : s; };
  const sf = (v, d) => { const s = nf(v, d); return v > 0 && Number(s.replace(",", ".")) !== 0 ? "+" + s : s; };
  const lerp = (a, b, t) => a + (b - a) * t;
