    /* บล็อก */
    nodeBox(ctx, P, C, xN, y1, bw, bh, ["วัตถุ"], C.ref, A(0), fs);
    nodeBox(ctx, P, C, xDl, y2, dw, bh, ["Δⁿ"], C.ref, A(1), fs);
    nodeBox(ctx, P, C, xN, y2, bw, bh, ["ИНС"], C.meas, A(2), fs);
    nodeBox(ctx, P, C, xN, y3, lbw, bh, ["บล็อกเรียน"], C.deep, A(2), fs);
