    tag(ctx, P, "x*(t)", fx(1) - 4, y1 - 12, C.ref, A(1), { size: fs, align: "right" });
    tag(ctx, P, "x*ₖ", (xDl - dw / 2 + xN + bw / 2) / 2, y2 - 11, C.ref, A(1), { size: fs, align: "center" });
    tag(ctx, P, "uН", (xN - bw / 2 + xSg + r) / 2, y2 - 11, C.meas, A(2), { size: fs, align: "center" });
    tag(ctx, P, "δu", xSg + 7, (y2 + y3) / 2, C.new, A(2), { size: fs });
    tag(ctx, P, "ปรับ w", xN + 7, (y2 + y3) / 2 + 2, C.deep, A(2), { size: fs - 0.5 });
    tag(ctx, P, "−", xSg + 8, y2 - r - 5, C.new, A(2), { size: fs + 1, align: "left", halo: 2 });
