    nodeBox(ctx, P, C, xP, y, bw, bh, ["วัตถุ"], C.lin, 1, fs);
    tag(ctx, P, "x*(t)", fx(0) + 4, y - 14, C.ref, 1, { size: fs });
    tag(ctx, P, "x*ₖ", (xD + bw * 0.3 + xN - bw / 2) / 2, y - 14, C.ref, 1, { size: fs, align: "center" });
    tag(ctx, P, "uН", (xN + bw / 2 + xP - bw / 2) / 2, y - 14, C.meas, 1, { size: fs, align: "center" });
    tag(ctx, P, "x(t)", fx(1) - 4, y - 14, C.lin, 1, { size: fs, align: "right" });
