      ctx.lineWidth = 1.4; ctx.strokeStyle = C.ink3; ctx.setLineDash([4, 3]); ctx.stroke(); ctx.setLineDash([]);
      P.label("บล็อกเรียน", xN, yg, C.ink3, { size: fs - 0.5, weight: 600, align: "center", halo: 0 });
      P.label("ถอดออก", xN, yg + bh / 2 + 11, C.crit, { size: fs - 0.5, weight: 700, align: "center", halo: 0 });
