    nums.innerHTML = (s.nums || []).map(n => '<div class="nr"><span class="nk">' + n.k + "</span>" +
      [].concat(n.v).map(v => '<span class="nv' + (n.big ? " big" : "") + '">' + v + "</span>").join("") +
      (n.note ? '<span class="nv"><span class="src-note">' + n.note + "</span></span>" : "") + "</div>").join("");
