            const mv = lerp(anim.from >= 3 ? 1 : 0, k >= 3 ? 1 : 0, anim.e);
            const lw_ = narrow ? 52 : 70, bx0 = B.x + lw_, bx1 = B.x + B.w - (narrow ? 42 : 50);
            const VX = v => bx0 + (v + 0.6) / 2.3 * (bx1 - bx0);
            const rh = Math.min(46, (B.h - 50) / 4), ry = i => B.y + 38 + (i + 0.5) * rh, bth = rh * 0.5;
            ctx.save(); ctx.globalAlpha *= 1 - mv;
