            P.arrow(xn + rn + 2, cy, xe - 14, cy, C.ink3, 1.6, 7);
            P.ring(xe, cy, 9, C.ok, 2.4);
            L("y* = " + nf(DY, 1), xe, cy + 24, C.ok, { size: fs - 0.5, align: "center" });
            const only6 = k === 6;
            L(only6 ? "w" : "w = " + nf(ws, 2).replace(/0$/, ""), lerp(xx, xn, 0.5), cy - 10 - 3.5 * ws, C.ref, { size: fs, align: "center" });
            L(only6 ? "y = w" : "y = " + nf(ws, 2).replace(/0$/, ""), xe - 8, cy - 22, C.new, { size: fs, align: "right" });
            const T = [null, null,
              ["ตั้งค่า: x = 1 · y* = " + nf(DY, 1) + " · η = " + nf(DETA, 1), "ความผิดพลาดเริ่มต้น |y − y*| = " + nf(ERR[0], 1)],
              ["Δw = −" + nf(DETA, 1) + "·(" + nf(RA[0], 1) + " − " + nf(DY, 1) + ") = +" + nf(dd(0), 1), "w = " + nf(RA[0], 1) + " + " + nf(dd(0), 1) + " = " + nf(RA[1], 1)],
              ["รอบ 2: Δw = +" + nf(dd(1), 1) + " → w = " + nf(RA[2], 1), "รอบ 3: Δw = +" + nf(dd(2), 1) + " → w = " + nf(RA[3], 1)],
              ["รอบ 4: Δw = +" + nf(dd(3), 2) + " → w = " + nf(RA[4], 2), "|y − y*| ลดเป็น " + nf(ERR[4], 2)],
              ["η = 1: w = " + nf(RB[1], 1) + " ทันที", "η = 2: " + RC.slice(0, 4).map(v => gn(v, 1)).join(" → ")]];
