              ctx.save(); ctx.globalAlpha *= a;
              L("+" + nf(HDW, 3), X(j + 0.5) + 4, Y(lerp(HW[j], HW[j + 1], 0.5)) + 15, C.deep, { size: fs - 0.5, align: "left", halo: 3 });
              ctx.restore();
