                const hi = ERR[j] < 0.15;      // ช่องแคบ: ย้ายป้ายขึ้นเหนือเส้นเป้า
                L(gn(ERR[j], 3), X(j) + 7, hi ? Y(DY) - 11 : (Y(RA[j]) + Y(DY)) / 2, C.crit, { size: fs, align: "left", halo: 3 });
