              ctx.beginPath(); ctx.moveTo(cx, pb + 1); ctx.lineTo(cx - 5, pb + 8); ctx.lineTo(cx + 5, pb + 8); ctx.closePath(); ctx.fillStyle = C.new; ctx.fill();
              T("จุดศูนย์ถ่วง = " + gn(cen, 2), cx, Y(0.5), C.new, narrow ? 11.5 : 13, { align: "center", weight: 700 });
