            /* ป้ายแกน */
            const tx = niceTicks(v.x0, v.x1, narrow ? 3 : 4), ty = niceTicks(v.y0, v.y1, 3);
            tx.vals.forEach(q => L(nf(q, tx.dec), X(q), py1 + 9, C.ink3, { size: 9.5, weight: 500, align: "center", halo: 2 }));
            ty.vals.forEach(q => L(nf(q, ty.dec), px0 - 4, Y(q), C.ink3, { size: 9.5, weight: 500, align: "right", halo: 2 }));
