            const cols = [{ h: "คู่", f: 0.16 }, { h: "ฝึกตัวแรก ทดสอบตัวหลัง", f: 0.42 }, { h: "ฝึกตัวหลัง ทดสอบตัวแรก", f: 0.42 }];
            const rh = narrow ? 16 : 18;
            const cell = (S, hl) => ({ t: "S = " + nf(S, 0) + " → y = " + yS(S), k: yS(S) ? C.crit : C.ink, b: yS(S) === 1 || hl });
