    const dx = bx - ax, dy = by - ay, len = Math.hypot(dx, dy) || 1, nx = -dy / len, ny = dx / len;
    const off = Math.abs(nx) * hw + Math.abs(ny) * hh + 4, cands = [];
    for (let n = 0; n <= 24; n++) {
      const t = 0.05 + 0.9 * n / 24, px = ax + dx * t, py = ay + dy * t;
      cands.push([px + nx * off, py + ny * off], [px - nx * off, py - ny * off]);
    }
